    total = 0
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    for item in numbers:
        try:
            total += item
        except TypeError as err:
            print(f"Skipping non-numeric item due to: {err}")
            continue
        except Exception as err:
            print(f"An unexpected error occurred with item: {item}. Error: {err}")
            continue
    try:
        return total
    except Exception as err:
        print(f"Error returning total: {err}")
        return None

