def filter_even(numbers):
    if not isinstance(numbers, list):
        try:
            raise TypeError("Input must be a list.")
        except TypeError as err:
            print(f"Error: {err}")
            return []

    even_numbers = []
    for item in numbers:
        try:
            num = int(item)
        except ValueError as err:
            print(f"Skipping non-integer value due to: {err}")
            continue
        except TypeError as err:
            print(f"Skipping non-numeric type due to: {err}")
            continue

        try:
            if num % 2 == 0:
                even_numbers.append(num)
        except TypeError as err:
            print(f"Cannot perform modulo on non-numeric type: {err}")
        except Exception as err:
            print(f"An unexpected error occurred during modulo check: {err}")

    try:
        if not all(isinstance(x, int) for x in even_numbers):
            raise ValueError("Internal error: non-integer found in even_numbers before return.")
    except ValueError as err:
        print(f"Validation error: {err}")

    return even_numbers

