def word_frequency(text):
    if not isinstance(text, str):
        try:
            raise TypeError("Input must be a string.")
        except TypeError as err:
            print(f"Error: {err}")
            return {}

    word_counts = {}
    try:
        cleaned_text = ''.join(char.lower() if char.isalpha() or char.isspace() else ' ' for char in text)
    except TypeError as err:
        print(f"Error during cleaning: {err}")
        return {}

    try:
        words = cleaned_text.split()
    except AttributeError as err:
        print(f"Error splitting text: {err}")
        return {}

    for word in words:
        try:
            if word:
                word_counts[word] = word_counts.get(word, 0) + 1
        except TypeError as err:
            print(f"Error processing word '{word}': {err}")
        except ValueError as err:
            print(f"Another error processing word '{word}': {err}")
        except Exception as err:
            print(f"Unexpected error processing word '{word}': {err}")

    try:
        if not word_counts:
            print("No words found in the text.")
    except Exception as err:
        print(f"Error checking for empty word_counts: {err}")

    return word_counts

