def calculate_average(numbers):
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return 0

    try:
        if not numbers:
            return 0
    except Exception as err:
        print(f"Unexpected error when checking if list is empty: {err}")
        return 0

    total = 0
    for num in numbers:
        try:
            total += float(num)
        except ValueError as err:
            print(f"Error converting item to float: {num}. Skipping. {err}")
            continue
        except TypeError as err:
            print(f"Error: Item in list is not a number: {num}. Skipping. {err}")
            continue

    try:
        count = len(numbers)
    except TypeError as err:
        print(f"Error getting length of numbers: {err}")
        return 0

    try:
        if count == 0:
            return 0
        average = total / count
    except ZeroDivisionError as err:
        print(f"Error: Division by zero, possibly all items were non-numeric. {err}")
        return 0
    except Exception as err:
        print(f"An unexpected error occurred during average calculation: {err}")
        return 0

    return average

