def simple_calculator(num1, operator, num2):
    try:
        num1 = float(num1)
    except ValueError as err:
        return f"Error: Invalid first number - {err}"

    try:
        num2 = float(num2)
    except ValueError as err:
        return f"Error: Invalid second number - {err}"

    try:
        if operator == '+':
            return num1 + num2
        elif operator == '-':
            return num1 - num2
        elif operator == '*':
            return num1 * num2
        elif operator == '/':
            try:
                if num2 == 0:
                    return 'Error'
                return num1 / num2
            except ZeroDivisionError as err:
                return f"Error: Division by zero - {err}"
        else:
            try:
                raise ValueError("Invalid operator")
            except ValueError as err:
                return f"Error: {err}"
    except TypeError as err:
        return f"Error: Type mismatch - {err}"
    except Exception as err:
