def count_lines_in_file(filepath):
    """
    Counts the number of lines in a given file.

    Args:
        filepath (str): The path to the file.

    Returns:
        int: The number of lines in the file.
    """
    line_count = 0
    try:
        if not isinstance(filepath, str):
            raise TypeError("Filepath must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return -1

    try:
        with open(filepath, 'r') as file:
            try:
                for line in file:
                    try:
                        line_count += 1
                    except Exception as err:
                        print(f"Error incrementing line count: {err}")
                        continue
            except IOError as err:
                print(f"Error reading file lines: {err}")
                return -1
            except Exception as err:
                print(f"An unexpected error occurred during line iteration: {err}")
                return -1
    except FileNotFoundError as err:
        print(f"Error: File not found at '{filepath}'. {err}")
        return -1
    except PermissionError as err:
        print(f"Error: Permission denied to open file '{filepath}'. {err}")
        return -1
    except Exception as err:
        print(f"An unexpected error occurred while opening or processing the file: {err}")
        return -1

    try:
        if line_count < 0:
            raise ValueError("Line count cannot be negative.")
    except ValueError as err:
        print(f"Internal error: {err}")
        return -1

    return line_count

