def most_frequent_char(text):
    if not isinstance(text, str):
        try:
            raise TypeError("Input must be a string.")
        except TypeError as err:
            print(f"Error: {err}")
            return None

    char_counts = {}
    for char in text:
        try:
            if char.isspace():
                continue
        except AttributeError as err:
            print(f"Error checking space: {err}")
            continue

        try:
            lower_char = char.lower()
        except AttributeError as err:
            print(f"Error converting to lowercase: {err}")
            continue

        try:
            char_counts[lower_char] = char_counts.get(lower_char, 0) + 1
        except Exception as err:
            print(f"Error updating character count: {err}")
            continue

    if not char_counts:
        try:
            raise ValueError("No valid characters found in the input string.")
        except ValueError as err:
            print(f"Error: {err}")
            return None

    max_count = -1
    most_frequent = None

    for char in text:
        try:
            if char.isspace():
                continue
        except AttributeError as err:
            print(f"Error checking space during iteration: {err}")
            continue

        try:
            lower_char = char.lower()
        except AttributeError as err:
            print(f"Error converting to lowercase during iteration: {err}")
            continue

        try:
            current_count = char_counts[lower_char]
        except KeyError as err:
            print(f"Error accessing character count for '{lower_char}': {err}")
            continue

        if current_count > max_count:
            max_count = current_count
            most_frequent = lower_char

    return most_frequent

