def seconds_to_hms(seconds):
    try:
        total_seconds = int(seconds)
    except ValueError as err:
        raise ValueError(f"Input must be an integer or convertible to int: {err}")
    except TypeError as err:
        raise TypeError(f"Input type error: {err}")

    if total_seconds < 0:
        raise ValueError("Seconds cannot be negative.")

    try:
        hours = total_seconds // 3600
    except Exception as err:
        raise RuntimeError(f"Error calculating hours: {err}")

    try:
        remaining_seconds_after_hours = total_seconds % 3600
    except Exception as err:
        raise RuntimeError(f"Error calculating remaining seconds for minutes: {err}")

    try:
        minutes = remaining_seconds_after_hours // 60
    except Exception as err:
        raise RuntimeError(f"Error calculating minutes: {err}")

    try:
        final_seconds = remaining_seconds_after_hours % 60
    except Exception as err:
        raise RuntimeError(f"Error calculating final seconds: {err}")

    try:
        return f"{hours:02d}:{minutes:02d}:{final_seconds:02d}"
    except Exception as err:
        raise RuntimeError(f"Error formatting output string: {err}")

