def matrix_add(matrix1, matrix2):
    try:
        rows1 = len(matrix1)
    except TypeError as err:
        raise ValueError(f"Matrix1 is not a list of lists: {err}")
    try:
        cols1 = len(matrix1[0])
    except IndexError as err:
        raise ValueError(f"Matrix1 is empty or has empty rows: {err}")
    try:
        rows2 = len(matrix2)
    except TypeError as err:
        raise ValueError(f"Matrix2 is not a list of lists: {err}")
    try:
        cols2 = len(matrix2[0])
    except IndexError as err:
        raise ValueError(f"Matrix2 is empty or has empty rows: {err}")

    if rows1 != rows2 or cols1 != cols2:
        raise ValueError("Matrices must have the same dimensions.")

    result = []
    for i in range(rows1):
        row_result = []
        for j in range(cols1):
            try:
                val1 = matrix1[i][j]
            except IndexError as err:
                raise ValueError(f"Error accessing element in matrix1: {err}")
            try:
                val2 = matrix2[i][j]
            except IndexError as err:
                raise ValueError(f"Error accessing element in matrix2: {err}")
            try:
                row_result.append(val1 + val2)
            except TypeError as err:
                raise ValueError(f"Matrix elements must be numbers for addition: {err}")
        result.append(row_result)
    return result

