def find_second_largest(numbers):
    try:
        if not isinstance(numbers, list):
            raise TypeError("Input must be a list.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if len(numbers) < 2:
            raise ValueError("List must contain at least two elements.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        unique_numbers = sorted(list(set(numbers)), reverse=True)
    except TypeError as err:
        print(f"Error: Could not sort or convert to set. {err}")
        return None
    except Exception as err:
        print(f"An unexpected error occurred during sorting/set conversion: {err}")
        return None

    try:
        if len(unique_numbers) < 2:
            raise ValueError("List must contain at least two distinct elements.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    try:
        second_largest = unique_numbers[1]
    except IndexError as err:
        print(f"Error: Could not access the second element. {err}")
        return None
    except Exception as err:
        print(f"An unexpected error occurred when accessing the element: {err}")
        return None

    return second_largest

