def run_length_encode(s):
    if not isinstance(s, str):
        try:
            raise TypeError("Input must be a string")
        except TypeError as err:
            return f"Error: {err}"

    if not s:
        return ""

    encoded_string = []
    try:
        count = 1
    except Exception as err:
        return f"Error initializing count: {err}"

    try:
        for i in range(1, len(s)):
            try:
                if s[i] == s[i - 1]:
                    count += 1
                else:
                    encoded_string.append(s[i - 1] + str(count))
                    count = 1
            except IndexError as err:
                return f"Error accessing string character: {err}"
            except TypeError as err:
                return f"Error with string concatenation or count conversion: {err}"
    except Exception as err:
        return f"Error during loop iteration: {err}"

    try:
        encoded_string.append(s[-1] + str(count))
    except IndexError as err:
        return f"Error appending last character: {err}"
    except TypeError as err:
        return f"Error with string concatenation or count conversion for last char: {err}"

    try:
        return "".join(encoded_string)
    except Exception as err:
        return f"Error joining encoded parts: {err}"

