def binary_to_decimal(binary_string):
    try:
        if not isinstance(binary_string, str):
            raise TypeError("Input must be a string.")
    except TypeError as err:
        print(f"Error: {err}")
        return None

    try:
        if not binary_string:
            raise ValueError("Input string cannot be empty.")
    except ValueError as err:
        print(f"Error: {err}")
        return None

    decimal_value = 0
    power = 0
    try:
        reversed_string = binary_string[::-1]
    except TypeError as err:
        print(f"Error during string reversal: {err}")
        return None

    for digit in reversed_string:
        try:
            if digit not in ('0', '1'):
                raise ValueError("Binary string can only contain '0' or '1'.")
        except ValueError as err:
            print(f"Error: {err}")
            return None

        try:
            int_digit = int(digit)
        except ValueError as err:
            print(f"Error converting character to integer: {err}")
            return None

        try:
            decimal_value += int_digit * (2 ** power)
        except OverflowError as err:
            print(f"Error during calculation due to large numbers: {err}")
            return None
        except TypeError as err:
            print(f"Type error during calculation: {err}")
            return None
        power += 1
    return decimal_value

